namespace sv_8346736ecdaa41a3ab8b0cda339d1377.Services;

public enum AppTheme { Light, Dark, System }

/// <summary>
/// Scoped service — one instance per circuit, so each user gets independent state.
/// Interactive components subscribe to <see cref="OnChanged"/> to re-render when
/// any other component mutates the theme or accent color.
/// </summary>
public sealed class ThemeService
{
    private AppTheme _theme = AppTheme.System;
    private string _accentColor = "#0d6efd";

    public AppTheme Theme
    {
        get => _theme;
        set { if (_theme != value) { _theme = value; NotifyChanged(); } }
    }

    public string AccentColor
    {
        get => _accentColor;
        set { if (_accentColor != value) { _accentColor = value; NotifyChanged(); } }
    }

    public event Action? OnChanged;

    private void NotifyChanged() => OnChanged?.Invoke();
}

@* Interactive island placed in the static layout — subscribes to ThemeService *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<span class="theme-indicator" style="color: @ThemeService.AccentColor;">
    @ThemeIcon @ThemeService.Theme
</span>

@code {
    private string ThemeIcon => ThemeService.Theme switch
    {
        AppTheme.Dark   => "🌙",
        AppTheme.Light  => "☀️",
        _               => "💻"
    };

    protected override void OnInitialized() => ThemeService.OnChanged += StateHasChanged;

    public void Dispose() => ThemeService.OnChanged -= StateHasChanged;
}

@* Quick toggle that can be placed anywhere (sidebar, header, etc.) *@
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<button class="btn btn-sm btn-outline-secondary" @onclick="CycleTheme"
        style="border-color: @ThemeService.AccentColor;">
    @ThemeIcon
</button>

@code {
    private string ThemeIcon => ThemeService.Theme switch
    {
        AppTheme.Dark   => "🌙",
        AppTheme.Light  => "☀️",
        _               => "💻"
    };

    private void CycleTheme()
    {
        ThemeService.Theme = ThemeService.Theme switch
        {
            AppTheme.Light  => AppTheme.Dark,
            AppTheme.Dark   => AppTheme.System,
            _               => AppTheme.Light
        };
    }

    protected override void OnInitialized() => ThemeService.OnChanged += StateHasChanged;

    public void Dispose() => ThemeService.OnChanged -= StateHasChanged;
}

@page "/settings"
@rendermode InteractiveServer
@implements IDisposable
@inject ThemeService ThemeService

<PageTitle>Settings</PageTitle>

<h1>User Preferences</h1>

<div class="mb-3">
    <label class="form-label">Theme</label>
    <select class="form-select" style="max-width:200px"
            value="@ThemeService.Theme"
            @onchange="OnThemeSelected">
        @foreach (var t in Enum.GetValues<AppTheme>())
        {
            <option value="@t">@t</option>
        }
    </select>
</div>

<div class="mb-3">
    <label class="form-label">Accent Color</label>
    <input type="color" class="form-control form-control-color"
           value="@ThemeService.AccentColor"
           @onchange="OnAccentChanged" />
</div>

<p>
    Current: <strong style="color:@ThemeService.AccentColor">@ThemeService.Theme</strong>
    — accent <span style="color:@ThemeService.AccentColor">@ThemeService.AccentColor</span>
</p>

@code {
    private void OnThemeSelected(ChangeEventArgs e)
    {
        if (Enum.TryParse<AppTheme>(e.Value?.ToString(), out var t))
            ThemeService.Theme = t;
    }

    private void OnAccentChanged(ChangeEventArgs e)
    {
        ThemeService.AccentColor = e.Value?.ToString() ?? "#0d6efd";
    }

    protected override void OnInitialized() => ThemeService.OnChanged += StateHasChanged;

    public void Dispose() => ThemeService.OnChanged -= StateHasChanged;
}

